changeSet.sql:
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='document' AND table_name='template' AND column_name='first_name_uz') THEN
        ALTER TABLE document.template RENAME COLUMN first_name_uz TO seller_name_uz;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='document' AND table_name='template' AND column_name='first_name_ru') THEN
        ALTER TABLE document.template RENAME COLUMN first_name_ru TO seller_name_ru;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='document' AND table_name='template' AND column_name='first_name_en') THEN
        ALTER TABLE document.template RENAME COLUMN first_name_en TO seller_name_en;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='document' AND table_name='template' AND column_name='second_name_uz') THEN
        ALTER TABLE document.template RENAME COLUMN second_name_uz TO buyer_name_uz;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='document' AND table_name='template' AND column_name='second_name_ru') THEN
        ALTER TABLE document.template RENAME COLUMN second_name_ru TO buyer_name_ru;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='document' AND table_name='template' AND column_name='second_name_en') THEN
        ALTER TABLE document.template RENAME COLUMN second_name_en TO buyer_name_en;
    END IF;
END $$;
